export const adaptiveJobs = seeds.map(([id, customer, summary, engineer, arrival, status, tone, queueIds]) => ({
  id,
  customer,
  summary,
  engineer,
  arrival,
  status,
  tone,
  queueIds: queueIds.includes('today') ? [...queueIds, 'week'] : queueIds,
  flagged: id === 'WO-4825',
})) satisfies readonly LumenAdaptiveJob[]

export function appShellAdaptiveFixture(
  mode: string | null = null,
  report: (action: string, value?: string) => void = () => {},
): LumenAppShellAdaptiveContent {
  const de = mode === 'localized'
  const labels: LumenAppShellAdaptiveContent['labels'] = de
    ? {
        queues: 'Aufträge',
        dispatch: 'Disposition',
        upcoming: 'Demnächst',
        archive: 'Archiv',
        openQueues: 'Aufträge öffnen',
        closeQueues: 'Aufträge schließen',
        closeOverlay: 'Auftragsmenü schließen',
        search: 'Aufträge suchen',
        hideSearch: 'Suche ausblenden',
        clearSearch: 'Suche löschen',
        empty: 'Keine passenden Aufträge',
        emptyDetail: 'Suche nach Kunde, Auftragsnummer oder Techniker.',
        emptyQueue: 'Keine Aufträge in dieser Warteschlange',
        emptyQueueDetail: 'Neue Aufträge werden hier angezeigt.',
        emptyCancelled: 'Keine stornierten Aufträge',
        emptyCancelledDetail: 'Stornierte Aufträge bleiben hier 90 Tage, bevor sie archiviert werden.',
        sort: 'Aufträge sortieren',
        time: 'Zeit',
        customer: 'Kunde',
        arrival: 'Ankunftsfenster',
        engineer: 'Techniker',
        book: 'Auftrag buchen',
        coverage: 'Schichtbelegung',
        coverageDetail: '8 von 12 Aufträgen zugeteilt',
        assign: 'Übrige zuteilen',
        accountName: 'Rosa Mendel',
        accountInitials: 'RM',
        accountRole: 'Disponentin',
        flag: (id) => `${id} zur Nachverfolgung markieren`,
        clearFlag: (id) => `Nachverfolgung von ${id} entfernen`,
        jobCount: (count) => `${count} Aufträge`,
      }
    : {
        queues: 'Queues',
        dispatch: 'Dispatch',
        upcoming: 'Upcoming',
        archive: 'Archive',
        openQueues: 'Open queues',
        closeQueues: 'Close queues',
        closeOverlay: 'Close queues overlay',
        search: 'Search jobs',
        hideSearch: 'Hide search',
        clearSearch: 'Clear search',
        empty: 'No jobs match that search',
        emptyDetail: 'Search covers the customer, the job number and the engineer.',
        emptyQueue: 'No jobs in this queue',
        emptyQueueDetail: 'New jobs will appear here.',
        emptyCancelled: 'No cancelled jobs',
        emptyCancelledDetail: 'Cancelled jobs stay here for 90 days before they are archived.',
        sort: 'Sort jobs',
        time: 'Time',
        customer: 'Customer',
        arrival: 'Arrival window',
        engineer: 'Engineer',
        book: 'Book job',
        coverage: 'Shift coverage',
        coverageDetail: '8 of 12 jobs assigned',
        assign: 'Assign remaining',
        accountName: 'Rosa Mendel',
        accountInitials: 'RM',
        accountRole: 'Dispatcher',
        flag: (id) => `Flag ${id} for follow-up`,
        clearFlag: (id) => `Clear follow-up on ${id}`,
        jobCount: (count) => `${count} ${count === 1 ? 'job' : 'jobs'}`,
      }
  const queue = (
    id: string,
    label: string,
    icon: LumenAppShellAdaptiveContent['queues'][number]['icon'],
    group: LumenAppShellAdaptiveContent['queues'][number]['group'],
    count?: number,
    mobile = false,
  ) => ({ id, label, icon, group, ...(count === undefined ? {} : { count }), mobile })
  const jobs =
    mode === 'empty'
      ? []
      : mode === 'one'
        ? adaptiveJobs.filter((job) => job.queueIds.includes('today')).slice(0, 1)
        : mode === 'boundary'
          ? Array.from({ length: 100 }, (_, index) => ({
              ...adaptiveJobs[index % adaptiveJobs.length]!,
              id: `WO-${5000 + index}`,
              queueIds: ['today'],
            }))
          : mode === 'overflow'
            ? Array.from({ length: 101 }, (_, index) => ({
                ...adaptiveJobs[index % adaptiveJobs.length]!,
                id: `WO-${5000 + index}`,
                queueIds: ['today'],
              }))
            : adaptiveJobs
  return {
    brand: 'Calder Field',
    brandMark: 'C',
    brandDetail: 'Dispatch',
    date: de ? 'Dienstag, 12. März' : 'Tuesday, 12 March',
    labels,
    queues: [
      queue('today', de ? 'Heute' : 'Today', 'today', 'dispatch', 12, true),
      queue('unassigned', de ? 'Nicht zugeteilt' : 'Unassigned', 'unassigned', 'dispatch', 4, true),
      queue('progress', de ? 'Unterwegs' : 'In progress', 'progress', 'dispatch', 2, true),
      queue('parts', de ? 'Wartet auf Teile' : 'Waiting on parts', 'parts', 'dispatch', 3),
      queue('tomorrow', de ? 'Morgen' : 'Tomorrow', 'tomorrow', 'upcoming', 6, true),
      queue('week', de ? 'Diese Woche' : 'This week', 'week', 'upcoming', 18),
      queue('completed', de ? 'Abgeschlossen' : 'Completed', 'completed', 'archive', 8, true),
      queue('cancelled', de ? 'Storniert' : 'Cancelled', 'cancelled', 'archive'),
    ],
    jobs,
    selectedQueueId: 'today',
    query: '',
    sort: 'time',
    onQueue: (id) => report('queue', id),
    onQuery: (value) => report('query', value),
    onSort: (value) => report('sort', value),
    onFlag: (id) => report('flag', id),
    onAction: (action) => report(action),
  }
}
